from qb import q, write

MS = ["backend-developer", "full-stack-developer", "python-developer", "data-scientist"]
ITEMS = [
    q("csharp", "easy", ["csharp"], "What is the difference between an interface and an abstract class in C#, and what is a record?", "An interface is a contract that a class can combine with others, while an abstract class can carry shared code and state but allows one base only. A record is a reference type designed for immutable data with value-based equality and easy copying.", ["Contract vs shared base", "Single inheritance", "Records: immutable, value equality"], ["When would you pick a record over a class?"]),
    q("csharp", "medium", ["collections"], "When would you choose a List, a Dictionary, a HashSet or a Queue in C#?", "List gives ordered indexed items, Dictionary gives fast lookup by key, HashSet gives fast membership and uniqueness and Queue gives first-in first-out processing. Choose by the operation you do most.", ["Four collections", "Choose by operation", "Lookup cost differences"], ["What does Dictionary do on a missing key?"]),
    q("csharp", "medium", ["memory"], "How does garbage collection work in .NET and what is IDisposable for?", "The garbage collector frees managed objects that are no longer reachable, at times it chooses. IDisposable releases unmanaged resources such as files and connections deterministically, usually with a using statement.", ["Reachability-based collection", "Unmanaged resources need Dispose", "using statement"], ["What happens if you forget to dispose a database connection?"]),
    q("dotnet", "medium", ["web-api"], "How would you validate input and return consistent errors in an ASP.NET Core API?", "Use model validation attributes or a validation library, return problem details with the right status code, handle unexpected exceptions in a global handler and never expose stack traces to clients.", ["Validation at the boundary", "Problem details responses", "Global exception handling"], ["How do you version the API?"]),
    q("dotnet", "medium", ["configuration"], "How do you manage configuration and secrets across development, test and production in .NET?", "Use layered configuration files and environment variables per environment and keep secrets in a secrets store such as Azure Key Vault, never in source control. Bind settings to typed classes.", ["Layered configuration", "Secrets in a vault", "Typed settings"], ["How do you avoid committing a secret by accident?"]),
    q("dotnet", "hard", ["entity-framework"], "What is the difference between tracking and no-tracking queries in Entity Framework and what is the N+1 problem?", "Tracking keeps entities so changes can be saved, but costs memory. No-tracking is faster for read-only queries. N+1 means loading related data with one query per row, which you fix with Include, projection or a join.", ["Tracking cost", "AsNoTracking for reads", "Include or projection against N+1"], ["How do you spot N+1 in logs?"]),
    q("sql-server", "easy", ["tsql"], "What is the difference between a clustered and a non-clustered index in SQL Server?", "A clustered index defines the physical order of the table's rows, so there is only one per table, while a non-clustered index is a separate structure with pointers to the rows and a table can have many.", ["Physical order vs separate structure", "One clustered per table", "Trade-offs for writes"], ["What is a key lookup?"]),
    q("sql-server", "medium", ["tsql"], "How would you write a query that returns the latest order for each customer in T-SQL?", "Use ROW_NUMBER() OVER (PARTITION BY CustomerId ORDER BY OrderDate DESC) in a common table expression and filter to row number 1, or use CROSS APPLY with TOP 1.", ["ROW_NUMBER with partition", "CTE and filter", "CROSS APPLY alternative"], ["How do you handle ties?"]),
    q("sql-server", "hard", ["performance"], "A stored procedure runs fast for some parameters and very slowly for others. What could be the reason?", "This is often parameter sniffing, where the cached plan suits the first parameter values but not others. Compare execution plans, update statistics and consider recompile hints, query rewrites or better indexes.", ["Parameter sniffing", "Compare plans", "Statistics, hints, indexes"], ["Why can OPTION (RECOMPILE) be costly?"]),
    q("data", "medium", ["etl"], "How would you design an ETL job that loads daily retail sales files into a data warehouse reliably?", "Land the files, validate their structure and totals, transform into the warehouse model, load idempotently with a batch id, log counts and reject bad rows with reasons, and alert on failures. Keep raw files for reruns.", ["Validate and reconcile", "Idempotent load with batch id", "Reject table and alerts"], ["How do you handle a file that arrives twice?"]),
    q("data", "medium", ["reporting"], "What is the difference between a fact table and a dimension table and what is a slowly changing dimension?", "A fact table stores measurements such as sales, and dimension tables describe them, such as product or store. A slowly changing dimension handles descriptive data that changes, for example by keeping history rows with validity dates.", ["Facts vs dimensions", "Grain of the fact table", "History with validity dates"], ["Which type of slowly changing dimension keeps full history?"]),
    q("data", "hard", ["power-bi"], "A Power BI report is slow and shows different totals than the source system. How do you investigate?", "Check the data model for relationships and filters, review measures and aggregation, compare row counts and totals stepwise back to the source, look for duplicates and refresh timing and reduce model size with import mode choices and summaries.", ["Trace totals step by step", "Model relationships and measures", "Performance of the model"], ["What is the difference between import and DirectQuery?"]),
    q("cloud", "medium", ["azure"], "What Azure services would you use to host a web API with a database and why?", "Azure App Service or containers run the API, Azure SQL Database provides a managed relational database, Key Vault stores secrets, Application Insights monitors it and a managed identity gives access without stored passwords.", ["Managed hosting and database", "Key Vault and managed identity", "Monitoring"], ["How would you scale the API?"]),
    q("cloud", "hard", ["messaging"], "When would you use a queue such as Azure Service Bus between services and how do you handle poison messages?", "Use a queue to decouple services, smooth spikes and retry safely. A poison message that always fails is moved after several attempts to a dead-letter queue for inspection, so it does not block others.", ["Decoupling and buffering", "Retries then dead-letter", "Idempotent consumers"], ["Why must consumers be idempotent?"]),
    q("retail", "medium", ["domain"], "How would you model products, prices and promotions for a retail system so that prices can change over time and past sales stay correct?", "Store prices with validity dates and keep the price actually charged on each sale line, so later price changes do not alter history. Model promotions as rules with periods and priorities.", ["Prices with validity periods", "Store the charged price on the sale", "Promotion rules and priority"], ["How do you handle two promotions that overlap?"]),
    q("retail", "hard", ["consistency"], "Many tills record sales offline and sync later. How do you avoid duplicates and conflicts?", "Give each sale a unique id created on the till, make the server accept it idempotently, sync in batches with retries and resolve conflicts such as stock with defined rules and reconciliation.", ["Unique id per sale", "Idempotent sync", "Conflict rules and reconciliation"], ["How would you handle a till whose clock is wrong?"]),
    q("oop", "medium", ["solid"], "What is dependency inversion and how does it help you test business logic?", "High-level logic should depend on abstractions, not concrete classes. Injecting an interface for the database or email lets tests supply fakes and makes implementations replaceable.", ["Depend on abstractions", "Inject dependencies", "Fakes in tests"], ["What is the difference from dependency injection?"]),
    q("oop", "medium", ["patterns"], "Explain the unit of work and repository patterns and a drawback of repositories over an ORM.", "A repository hides data access behind an interface and a unit of work groups changes into one transaction. With an ORM that already does both, an extra repository layer can add boilerplate without benefit.", ["Repository hides storage", "Unit of work is one transaction", "Possible redundant layer"], ["When is a repository still worth it?"]),
    q("python", "easy", ["python"], "Compare Python and C# for a data processing task and say when you would use each.", "Python is quick to write with strong data libraries such as pandas, so it suits analysis and scripting, while C# is strongly typed and fast, fitting large maintainable services and Microsoft-stack applications. Choose by team skills and the ecosystem.", ["Productivity vs type safety", "Data libraries", "Match the ecosystem"], ["How could they work together?"], roles=["python-developer", "data-scientist", "backend-developer"]),
    q("testing", "medium", ["testing"], "How do you write tests for an ASP.NET Core API without a real database?", "Use unit tests with fakes for the services and integration tests with an in-memory or containerised test database, call endpoints through a test server and check status codes and results.", ["Fakes for unit tests", "Test server for integration", "Isolated test data"], ["Why is the in-memory provider not a perfect substitute?"]),
    q("confiz-scenario", "medium", ["debugging"], "Scenario: month-end sales totals in the report are lower than in the point-of-sale system. How do you find out why?", "Reconcile at day, store and transaction level to find where totals diverge, check for failed or late loads, duplicates removed by mistake, time zone cut-offs and filters in the report, then fix and add a daily reconciliation check.", ["Narrow the difference", "Check loads, duplicates, cut-offs", "Permanent reconciliation"], ["How would you explain it to the business?"], kind="scenario"),
    q("confiz-scenario", "hard", ["design"], "Scenario: design a dashboard backend that lets a retail manager see today's sales by store within a minute of each sale.", "Stream sales events into a queue, aggregate them incrementally into a fast store or summary tables, serve the dashboard from those summaries and reconcile with the full data later. Handle late and duplicate events.", ["Event stream", "Incremental aggregation", "Reconcile and handle duplicates"], ["What if a store's connection is down?"], kind="scenario"),
    q("confiz-scenario", "easy", ["teamwork"], "Scenario: a client reports a bug you cannot reproduce. What do you do?", "Ask for exact steps, data, time and environment, check logs and monitoring around that time, try to reproduce with similar data and add logging if needed. Keep the client informed.", ["Gather precise details", "Check logs", "Communicate"], ["When do you add extra logging in production?"], kind="scenario"),
    q("git", "easy", ["git"], "How does your team use Git branches and pull requests, and what makes a good pull request?", "Work on a short-lived branch per change, open a pull request with a clear description, linked task and tests, keep it small so it can be reviewed quickly and respond to review comments. Merge after checks pass.", ["Branch per change", "Small, described, tested", "Review before merge"], ["How do you handle a conflict with the main branch?"]),
    q("project", "easy", ["projects"], "Describe a project using C#, .NET, SQL or data tools that you built. What was your part and what went wrong first?", "A strong answer names the project, your own part and the stack, a real problem and its fix, and how you tested it.", ["Own part and stack", "A real problem and fix", "Testing"], ["What would you change?"], kind="scenario", roles=MS + ["frontend-developer"]),
]


def build():
    return write("confiz", MS, ITEMS)


if __name__ == "__main__":
    build()
